package org.dromara.sports.tables.d10.result_version;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import lombok.RequiredArgsConstructor;
import org.dromara.common.satoken.utils.LoginHelper;
import org.dromara.sports.api.GrowthFactApi;
import org.dromara.sports.api.OrganizationSessionApi;
import org.dromara.sports.api.OrganizationQualificationApi;
import org.dromara.sports.platform.core.*;
import org.springframework.stereotype.Service;
import java.time.OffsetDateTime;
import java.time.ZoneOffset;
import java.time.format.DateTimeFormatter;
import java.util.*;
import static org.dromara.sports.platform.core.BusinessSupport.*;

/** Corrections preserve the old version and invalidate affected proof claims pending human re-award. */
@Service @RequiredArgsConstructor
public class ResultRevisionService implements CapabilityProvider {
    private final ScopedJdbc db;private final ObjectMapper json;private final GrowthFactApi growth;
    private final OrganizationSessionApi organizations;private final OrganizationQualificationApi qualifications;
    private static final Set<String> READS=Set.of("asp_result_version","asp_result_item","asp_match","asp_match_entry","asp_stage","asp_competition_unit","asp_event","asp_registration","asp_registration_member","asp_roster_member","asp_roster_version","asp_account","asp_person","asp_team","asp_team_member","asp_sport","asp_checkin","asp_growth_record","asp_growth_profile","asp_growth_policy","asp_title_equipment","asp_honor");
    private static final Set<String> WRITES=Set.of("asp_result_version","asp_result_item","asp_match","asp_notification","asp_honor","asp_growth_record","asp_growth_profile","asp_growth_policy","asp_title_equipment","asp_event");
    public List<CapabilityDefinition> capabilities(){return List.of(
        capability(json,"result.correct","更正正式赛果并通知相关成员","asp_result_version",false,true,Set.of("organizer"),"",READS,WRITES,"matchId","expectedVersion","summary","games?","outcomeA","outcomeB","reason"),
        capability(json,"result.void","撤销无效赛果并回退相关成长与证明","asp_result_version",false,true,Set.of("organizer"),"",READS,WRITES,"matchId","expectedVersion","reason"),
        capability(json,"match.schedule","安排或调整场次时间和球场","asp_result_version",true,true,Set.of("organizer"),"",READS,Set.of("asp_match","asp_notification"),"matchId","expectedVersion","startsAt","endsAt","courtName"));}
    public JsonNode preview(String code,JsonNode in){var match=owned(id(in,"matchId"));var out=json.createObjectNode();out.set("match",safeJson(json,match));out.set("versions",safeJson(json,db.list("SELECT id,revision,status,raw_performance::text AS performance,decision::text AS decision,confirmed_at FROM asp_result_version WHERE match_id=? ORDER BY revision DESC",id(in,"matchId"))));return out;}
    public JsonNode execute(String code,JsonNode in){long matchId=id(in,"matchId");var match=owned(matchId);long event=number(match.get("event_id"));db.lock("event-fixtures:"+event);match=owned(matchId);if(number(match.get("version"))!=in.path("expectedVersion").asLong(-1))throw fail("场次已变化，请重新核对",409);
        if(code.equals("match.schedule")){if(Set.of("completed","confirmed","cancelled").contains(match.get("status")))throw fail("已结束场次不再重新排期",409);if(!"normal".equals(match.get("holding_status")))throw fail("取消赛事只保留历史安排",409);OffsetDateTime start=parse(text(in,"startsAt",40)),end=parse(text(in,"endsAt",40));String court=text(in,"courtName",80);if(!end.isAfter(start))throw fail("结束时间须晚于开始时间",400);if(!start.isAfter(OffsetDateTime.now()))throw fail("请安排未来的场次时间",409);if(match.get("starts_at")!=null&&start.isBefore(parse(match.get("starts_at").toString()))||match.get("ends_at")!=null&&end.isAfter(parse(match.get("ends_at").toString())))throw fail("场次时间须在赛事举办范围内",409);if(db.count("SELECT count(*) FROM asp_match m JOIN asp_stage s ON s.id=m.stage_id JOIN asp_competition_unit u ON u.id=s.unit_id WHERE u.event_id=? AND m.id<>? AND m.status<>'cancelled' AND m.scheduled_start<? AND m.scheduled_end>? AND (m.court_name=? OR EXISTS(SELECT 1 FROM asp_match_entry a JOIN asp_match_entry b ON b.registration_id=a.registration_id WHERE a.match_id=m.id AND b.match_id=?))",event,matchId,end,start,court,matchId)>0)throw fail("该时间的球场或参赛名单已有其他场次，请调整",409);db.update("UPDATE asp_match SET scheduled_start=?,scheduled_end=?,court_name=?,version=version+1,update_time=CURRENT_TIMESTAMP WHERE id=?",start,end,court,matchId);notify(matchId,event,match.get("tenant_id").toString(),"场次安排已更新",court+" · "+start+"—"+end,number(match.get("version"))+1);return reference(json,"matchId",matchId,"scheduled");}
        if(TrustedRunContext.current()!=null)throw fail("正式赛果更正必须由责任人本人提交",403);db.lock("result:"+matchId);var current=db.one("SELECT * FROM asp_result_version WHERE match_id=? AND status IN ('confirmed','void') ORDER BY revision DESC LIMIT 1 FOR UPDATE",matchId);if(current==null)throw fail("只有已确认正式赛果可以更正",409);if(code.equals("result.void")){if(!"confirmed".equals(current.get("status")))throw fail("该赛果已撤销",409);String reason=text(in,"reason",2000);long revision=number(current.get("revision"))+1,result=nextId();var decision=json.createObjectNode().put("reason",reason).put("previousId",current.get("id").toString());db.update("UPDATE asp_result_version SET status='superseded',version=version+1,update_time=CURRENT_TIMESTAMP WHERE id=?",current.get("id"));db.update("INSERT INTO asp_result_version(id,tenant_id,match_id,revision,previous_id,status,raw_performance,decision,confirmer_id,confirmed_at) VALUES (?,?,?,?,?,'void','{}'::jsonb,?::jsonb,?,CURRENT_TIMESTAMP)",result,match.get("tenant_id"),matchId,revision,current.get("id"),decision.toString(),LoginHelper.getUserId());suspendProofs(matchId,event,result);db.update("UPDATE asp_match SET version=version+1,update_time=CURRENT_TIMESTAMP WHERE id=?",matchId);db.update("UPDATE asp_event SET closure_status='wrap_up',version=version+1,update_time=CURRENT_TIMESTAMP WHERE id=? AND closure_status='closed'",event);growth.reconcileEvent(event);notify(matchId,event,match.get("tenant_id").toString(),"本场赛果已撤销",reason+"；相关成长已追加调整，获奖证明待重新核实。",number(match.get("version"))+1);return reference(json,"resultId",result,"void");}String a=text(in,"outcomeA",16),b=text(in,"outcomeB",16);if(!(a.equals("win")&&b.equals("loss")||a.equals("loss")&&b.equals("win")||a.equals("draw")&&b.equals("draw")))throw fail("双方结果须为一胜一负，或同时平局",400);String reason=text(in,"reason",2000),summary=text(in,"summary",1000),games=in.path("games").asText("");if(games.length()>2000)throw fail("分局说明过长",400);long revision=number(current.get("revision"))+1,result=nextId();var raw=json.createObjectNode();raw.put("summary",summary);raw.put("games",games);raw.put("outcomeA",a);raw.put("outcomeB",b);raw.put("canonical",summary+"\n"+games+"\n"+a+"\n"+b);var decision=json.createObjectNode();decision.put("reason",reason);decision.put("previousId",current.get("id").toString());db.update("UPDATE asp_result_version SET status='superseded',version=version+1,update_time=CURRENT_TIMESTAMP WHERE id=?",current.get("id"));db.update("INSERT INTO asp_result_version(id,tenant_id,match_id,revision,previous_id,status,raw_performance,decision,confirmer_id,confirmed_at,published_at) VALUES (?,?,?,?,?,'confirmed',?::jsonb,?::jsonb,?,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)",result,match.get("tenant_id"),matchId,revision,current.get("id"),raw.toString(),decision.toString(),LoginHelper.getUserId());for(var side:db.list("SELECT id,slot FROM asp_match_entry WHERE match_id=?",matchId)){var components=json.createObjectNode();components.put("outcome","A".equals(side.get("slot"))?a:b);db.update("INSERT INTO asp_result_item(id,tenant_id,result_version_id,match_entry_id,performance_status,unit,components) VALUES (?,?,?,?,'valid','point',?::jsonb)",nextId(),match.get("tenant_id"),result,side.get("id"),components.toString());}suspendProofs(matchId,event,result);db.update("UPDATE asp_match SET version=version+1,update_time=CURRENT_TIMESTAMP WHERE id=?",matchId);db.update("UPDATE asp_event SET closure_status='wrap_up',version=version+1,update_time=CURRENT_TIMESTAMP WHERE id=? AND closure_status='closed'",event);growth.reconcileEvent(event);notify(matchId,event,match.get("tenant_id").toString(),"正式赛果已更正","结果第"+revision+"版。相关获奖证明待主办方重新核对；成长记录已同步更新。",number(match.get("version"))+1);return reference(json,"resultId",result,"confirmed");
    }
    public Map<String,Object> owned(long match){var org=organizations.managedOrganization(BusinessIdentity.getUserId()).orElseThrow(()->fail("请进入主办方工作台",403));if(!qualifications.hasStaffAction(org.tenantId(),org.organizationId(),org.accountId(),"organize"))throw fail("当前岗位没有赛务权限",403);var row=db.one("SELECT m.*,u.event_id,e.organization_id,e.holding_status,e.starts_at,e.ends_at FROM asp_match m JOIN asp_stage s ON s.id=m.stage_id JOIN asp_competition_unit u ON u.id=s.unit_id JOIN asp_event e ON e.id=u.event_id WHERE m.id=? AND e.organization_id=? AND e.tenant_id=?",match,org.organizationId(),org.tenantId());if(row==null)throw fail("场次不在当前组织范围",403);return row;}
    public JsonNode fixtures(long event){var org=organizations.managedOrganization(LoginHelper.getUserId()).orElseThrow(()->fail("请进入主办方工作台",403));if(!qualifications.hasStaffAction(org.tenantId(),org.organizationId(),org.accountId(),"organize"))throw fail("当前岗位没有赛务权限",403);if(db.count("SELECT count(*) FROM asp_event WHERE id=? AND organization_id=? AND tenant_id=?",event,org.organizationId(),org.tenantId())==0)throw fail("赛事不在当前组织范围",403);return safeJson(json,db.list("SELECT m.id,m.code,m.version,m.status,e.holding_status,m.court_name,m.scheduled_start,m.scheduled_end,u.id AS unit_id,u.name AS unit_name,(SELECT raw_performance::text FROM asp_result_version v WHERE v.match_id=m.id AND v.status IN ('confirmed','void') ORDER BY revision DESC LIMIT 1) AS performance,(SELECT string_agg(rm.person_snapshot->>'legalName','、' ORDER BY rm.id) FROM asp_match_entry me JOIN asp_roster_member rm ON rm.roster_version_id=me.roster_version_id WHERE me.match_id=m.id AND me.slot='A') AS side_a,(SELECT string_agg(rm.person_snapshot->>'legalName','、' ORDER BY rm.id) FROM asp_match_entry me JOIN asp_roster_member rm ON rm.roster_version_id=me.roster_version_id WHERE me.match_id=m.id AND me.slot='B') AS side_b,(SELECT revision FROM asp_result_version v WHERE v.match_id=m.id AND v.status IN ('confirmed','void') ORDER BY revision DESC LIMIT 1) AS result_revision,(SELECT status FROM asp_result_version v WHERE v.match_id=m.id AND v.status IN ('confirmed','void') ORDER BY revision DESC LIMIT 1) AS result_status FROM asp_match m JOIN asp_stage s ON s.id=m.stage_id JOIN asp_competition_unit u ON u.id=s.unit_id JOIN asp_event e ON e.id=u.event_id WHERE u.event_id=? ORDER BY m.scheduled_start NULLS LAST,u.id,m.code,m.id",event));}
    /** Only current claims whose recorded project/matches changed need review. */
    private void suspendProofs(long matchId,long event,long result) {
        var unit=db.one("SELECT s.unit_id FROM asp_match m JOIN asp_stage s ON s.id=m.stage_id WHERE m.id=?",matchId);
        var rows=db.list("SELECT id,registration_id,person_id,award_key,title,status,source::text AS source_text FROM asp_honor WHERE event_id=? AND category='event' AND award_key IS NOT NULL",event);
        List<EventAwardLineage.Claim> claims=new ArrayList<>();
        for(var h:rows)try{claims.add(new EventAwardLineage.Claim(number(h.get("id")),number(h.get("registration_id")),number(h.get("person_id")),h.get("award_key").toString(),h.get("title").toString(),json.readTree(h.get("source_text").toString()),h.get("status").toString()));}catch(Exception e){throw fail("相关获奖依据无法读取，请先核对",409);}
        for(var h:EventAwardLineage.latest(claims)) {
            boolean participant=db.count("SELECT count(*) FROM asp_match_entry WHERE match_id=? AND registration_id=?",matchId,h.registration())>0;
            if("verified".equals(h.status())&&EventAwardLineage.dependsOn(h.source(),matchId,number(unit.get("unit_id")),participant)) {
                var source=(com.fasterxml.jackson.databind.node.ObjectNode)h.source().deepCopy();
                source.put("reviewMatchId",String.valueOf(matchId)).put("reviewResultId",String.valueOf(result));
                db.update("UPDATE asp_honor SET status='suspended',source=?::jsonb,version=version+1,update_time=CURRENT_TIMESTAMP WHERE id=? AND status='verified'",source.toString(),h.id());
            }
        }
    }

    private OffsetDateTime parse(String text){try{return OffsetDateTime.parse(text);}catch(Exception e){try{return java.time.LocalDateTime.parse(text.replace(' ','T')).atOffset(ZoneOffset.ofHours(8));}catch(Exception bad){throw fail("请填写北京时间，或包含时区的完整时间",400);}}}
    private void notify(long match,long event,String tenant,String title,String body,long revision){for(var account:db.list("SELECT DISTINCT a.id FROM asp_match_entry me JOIN asp_roster_member rm ON rm.roster_version_id=me.roster_version_id JOIN asp_account a ON a.person_id=rm.person_id WHERE me.match_id=? AND a.status='active'",match)){var content=json.createObjectNode();content.put("title",title);content.put("body",body);content.put("target","/portal/results");db.update("INSERT INTO asp_notification(id,tenant_id,recipient_account_id,business_type,business_id,business_revision,purpose,content,dedupe_key) VALUES (?,?,?,'match',?,?,'schedule-or-result',?::jsonb,?)",nextId(),tenant,account.get("id"),match,revision,content.toString(),"match:"+match+":"+revision);}}
}


